package glitch

import data.glitch_lib

# Password-related field name patterns - matching at end of name or before underscore
password_field_patterns := {"password", "passwd", "pwd", "secret", "credentials", "credential", "token"}

# Check for empty or null values
is_empty_or_null_value(val) {
    val.ir_type == "String"
    val.value == ""
} else {
    val.ir_type == "Null"
} else {
    val.ir_type == "Undef"
}

# Check for sensitive credential field names - match as whole word or at end
is_sensitive_field_name(name) {
    pattern := password_field_patterns[_]
    lower_name := lower(name)
    endswith(lower_name, pattern)
} else {
    pattern := password_field_patterns[_]
    lower_name := lower(name)
    regex.match(sprintf("(^|_)(password|passwd|pwd|secret|credentials?|token)(_)?$"), lower_name)
}

# Check Hash values that contain empty sensitive credentials
check_hash_sensitive_empty(val) = matches {
    val.ir_type == "Hash"
    matches = {{"key": key_expr.value, "value": inner_val} |
        some key_expr
        val.value[key_expr]
        is_sensitive_field_name(key_expr.value)
        is_empty_or_null_value(val.value[key_expr])
        inner_val := val.value[key_expr]
    }
}

# Walk Assign nodes in conditional statements and statements
walk_statements(node, matches) {
    node.ir_type == "ConditionalStatement"
    some stmt in node.statements
    walk_statements(stmt, matches)
} else {
    node.ir_type == "ConditionalStatement"
    walk_statements(node.condition, matches)
} else {
    node.ir_type == "Block"
    some stmt in node.statements
    walk_statements(stmt, matches)
} else {
    node.ir_type == "BlockExpr"
    some stmt in node.statements
    walk_statements(stmt, matches)
} else {
    node.ir_type == "Assign"
    is_sensitive_field_name_node(node.left)
    is_empty_or_null_value(node.right)
    matches = {"left": node.left, "right": node.right, "node": node}
}

# Extract variable name from Access chain or VariableReference
is_sensitive_field_name_node(node) {
    node.ir_type == "Access"
    leaf_name := get_access_leaf_name(node)
    is_sensitive_field_name(leaf_name)
}

get_access_leaf_name(node) = name {
    node.ir_type == "Access"
    name := get_access_leaf_name(node.right)
} else {
    node.ir_type == "String"
    name := node.value
} else {
    node.ir_type == "VariableReference"
    name := node.value
} else {
    name := ""
}

# Check statements in UnitBlock for Assign patterns with sensitive field names
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    some stmt in parent.statements
    matches := walk_statements(stmt, _)
    matches != null

    result := {
        "type": "sec_empty_pass",
        "element": matches.node,
        "path": parent.path,
        "description": "Empty or null password value - Password and credential fields should not be empty or null. (CWE-258)"
    }
}

# Direct variable check
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    vars := glitch_lib.all_variables(parent)
    node := vars[_]
    is_sensitive_field_name(node.name)
    is_empty_or_null_value(node.value)

    result := {
        "type": "sec_empty_pass",
        "element": node,
        "path": parent.path,
        "description": "Empty or null password value - Password and credential fields should not be empty or null. (CWE-258)"
    }
}

# Atomic unit attributes check
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    is_sensitive_field_name(attr.name)
    is_empty_or_null_value(attr.value)

    result := {
        "type": "sec_empty_pass",
        "element": attr,
        "path": parent.path,
        "description": "Empty or null password value - Password and credential fields should not be empty or null. (CWE-258)"
    }
}

# Check attributes in nested unit_blocks (Puppet class parameters)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    nested_blocks := parent.unit_blocks[_]
    attrs := nested_blocks.attributes[_]
    is_sensitive_field_name(attrs.name)
    is_empty_or_null_value(attrs.value)

    result := {
        "type": "sec_empty_pass",
        "element": attrs,
        "path": parent.path,
        "description": "Empty or null password value - Password and credential fields should not be empty or null. (CWE-258)"
    }
}

# Check Hash values in variables
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    vars := glitch_lib.all_variables(parent)
    node := vars[_]

    matches := check_hash_sensitive_empty(node.value)
    _ := matches[_]

    result := {
        "type": "sec_empty_pass",
        "element": node,
        "path": parent.path,
        "description": "Empty or null password value - Password and credential fields should not be empty or null. (CWE-258)"
    }
}

# Check Array items containing Hash values in variables
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    vars := glitch_lib.all_variables(parent)
    node := vars[_]

    node.value.ir_type == "Array"
    array_item := node.value.value[_]
    array_item.ir_type == "Hash"

    matches := check_hash_sensitive_empty(array_item)
    _ := matches[_]

    result := {
        "type": "sec_empty_pass",
        "element": node,
        "path": parent.path,
        "description": "Empty or null password value - Password and credential fields should not be empty or null. (CWE-258)"
    }
}

